// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 guess) public {
        // keep the actor from being the test contract or zero address
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // give the actor enough ether to play the game
        vm.deal(actor, 2 ether);

        // actor locks in a guess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // advance to a block where settle() can proceed
        vm.roll(block.number + 2);

        // record whether the first settle succeeded (reference: it clears block, second should fail)
        bool firstOk;
        vm.prank(actor);
        try c.settle() {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        // the reference always zeroes the block; the bug leaves it set
        bool secondOk;
        vm.prank(actor);
        try c.settle() {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // Reference: block is always cleared by the first settle, so a second settle must revert.
        // Mutant: block remains, so a second settle can proceed (and may transfer again).
        assertTrue(!(firstOk && secondOk));
    }
}
